async function fight(pat, timeout=60000){
  const npc=sdk.findNearbyNpc(pat); if(!npc) return 'no '+pat;
  console.log('fight',npc.name,npc.combatLevel,npc);
  const r=await bot.attack(npc); console.log('attack',r);
  const start=Date.now();
  while(Date.now()-start<timeout){
    await sdk.waitForTicks(2);
    const s=sdk.getState(); if(!s) continue;
    if(s.player.isDead) return 'died';
    if(s.player.hp<=4){ await bot.eatFood().catch(()=>{}); }
    const still=sdk.getNearbyNpcs().find(n=>n.index===npc.index);
    // console.log('hp',s.player.hp,'inCombat',s.player.combat.inCombat,'still',!!still, still?.hp)
    if(!still && !s.player.combat.inCombat) return 'killed? '+npc.name+' hp'+s.player.hp+' skills '+sdk.getSkills().filter(x=>['Attack','Strength','Defence','Hitpoints'].includes(x.name)).map(x=>x.name+x.baseLevel).join(',');
    if(!s.player.combat.inCombat && still){ // reattack
      await bot.attack(still).catch(e=>console.log(e));
    }
  }
  return 'timeout '+npc.name;
}
